using NUnit.Framework;

[TestFixture]
public class ShareCommonElementTests
{
    [Test]
    public void Returns_True_When_Common_Element_Exists()
    {
        var result = ShareCommonElement(new[] { 1, 2, 3 }, new[] { 5, 3, 9 });
        Assert.That(result, Is.True);
    }

    private bool ShareCommonElement(int[] nums1, int[] nums2)
    {
        var seen = new HashSet<int>(nums1);

        foreach (var num in nums2)
        {
            if (seen.Contains(num))
                return true;
        }

        return false;
    }
}
